-- Sword Health — Здоров'я та краса › Реабілітація та фізіотерапія
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'swordhealth.com' OR LOWER(`name`) = LOWER('Sword Health'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Sword Health', NULL, 'https://swordhealth.com', NULL, NULL, 'Цифрова фізіотерапія вдома: AI-асистент Phoenix веде сесію вправ, слухає, як ви почуваєтесь, і на ходу змінює складність, а фізичний терапевт стежить за прогресом дистанційно.', 'Digital physical therapy at home: the Phoenix AI assistant guides your exercise session, listens to how you feel and adjusts difficulty on the fly, while a physical therapist monitors progress remotely.', 'Sword Health — платформа цифрової допомоги при болю в суглобах, спині та м''язах. Основна програма Thrive поєднує вправи вдома з датчиками руху й планшетом, AI-асистента Phoenix і живого фізичного терапевта. Phoenix супроводжує сесію: з ним можна говорити, він дає зворотний зв''язок щодо техніки та в реальному часі змінює складність і тривалість вправ. Терапевт переглядає результати й коригує план. Крім реабілітації опорно-рухового апарату, компанія має програми для здоров''я тазового дна та інші напрями, а до компанії приєдналася Kaia Health. Доступ зазвичай надають роботодавці та страхові плани, часто без оплати для учасника; ціни для приватних осіб не опубліковано. Сервіс не замінює очного лікаря при гострій травмі.', 'Sword Health is a digital care platform for joint, back and muscle pain. Its core programme, Thrive, combines home exercise with motion sensors and a tablet, the Phoenix AI assistant and a real physical therapist. Phoenix guides each session: you can talk to it, it gives feedback on form and adjusts exercise difficulty and duration in real time. The therapist reviews results and adjusts the plan. Beyond musculoskeletal rehab, the company runs pelvic health and other programmes, and Kaia Health has joined the company. Access is usually provided by employers and health plans, often at no cost to the member; prices for individuals are not published. The service does not replace an in-person doctor for an acute injury.', 'AI-асистент Phoenix веде сесію й змінює складність у реальному часі
Датчики руху та планшет для вправ удома
Дистанційний супровід фізичного терапевта
Програми для спини, суглобів і тазового дна', 'Phoenix AI assistant guides sessions and adapts difficulty in real time
Motion sensors and a tablet for home exercise
Remote support from a physical therapist
Programmes for back, joints and pelvic health', 'Працівники й застраховані, яким роботодавець чи страховий план надає програму реабілітації при хронічному болю в спині й суглобах.', 'Employees and plan members whose employer or health plan offers a rehab programme for chronic back and joint pain.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
