INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', 'Sword Health is a digital care platform for joint, back and muscle pain. Its core programme, Thrive, combines home exercise with motion sensors and a tablet, the Phoenix AI assistant and a real physical therapist. Phoenix guides each session: you can talk to it, it gives feedback on form and adjusts exercise difficulty and duration in real time. The therapist reviews results and adjusts the plan. Beyond musculoskeletal rehab, the company runs pelvic health and other programmes, and Kaia Health has joined the company. Access is usually provided by employers and health plans, often at no cost to the member; prices for individuals are not published. The service does not replace an in-person doctor for an acute injury.', 'manual' FROM DUAL WHERE @new = 1;
