-- Kemtai — Здоров'я та краса › Реабілітація та фізіотерапія
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'kemtai.com' OR LOWER(`name`) = LOWER('Kemtai'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Kemtai', NULL, 'https://www.kemtai.com', NULL, NULL, 'Відстеження рухів через звичайну камеру для фізіотерапії: аналізує 111 точок тіла й підказує, як виправити техніку вправи, без датчиків і без встановлення застосунку.', 'Motion tracking through an ordinary camera for physical therapy: it analyses 111 body points and cues you to correct exercise form, with no sensors and no app to install.', 'Kemtai — веб-платформа для фізіотерапії та тренувань із відстеженням рухів за допомогою комп''ютерного зору. Камера телефона, планшета чи ноутбука фіксує 111 точок на тілі пацієнта — суглоби, обертання, положення хребта, — а система в реальному часі дає голосові й візуальні підказки щодо техніки. Обробка відбувається на самому пристрої, без запису відео. Бібліотека містить понад 2000 варіантів вправ; клініцисти призначають програми та стежать за виконанням через Kemtai CARE, а цифрові сервіси можуть вбудувати технологію через API. Напрями — опорно-руховий апарат, неврологічна реабілітація, дистанційний терапевтичний моніторинг. Продукт орієнтований на клініки та компанії; ціни не опубліковано.', 'Kemtai is a web platform for physical therapy and fitness with computer-vision motion tracking. The camera of a phone, tablet or laptop tracks 111 points on the patient''s body — joints, rotations, spine position — and the system gives real-time audio and visual cues on form. Processing happens on the device itself, with no video recorded. The library has more than 2,000 exercise variations; clinicians assign programmes and monitor adherence in Kemtai CARE, and digital health services can embed the technology via API. Use cases include musculoskeletal care, neurological rehabilitation and remote therapeutic monitoring. The product targets clinics and companies; pricing is not published.', 'Відстеження 111 точок тіла через камеру без датчиків
Підказки щодо техніки в реальному часі
Понад 2000 варіантів вправ
Кабінет клініциста Kemtai CARE і API для інтеграції', 'Tracks 111 body points through a camera, no sensors
Real-time cues on exercise form
More than 2,000 exercise variations
Kemtai CARE clinician portal and an integration API', 'Фізіотерапевтичні клініки, лікарні та цифрові сервіси здоров''я, які ведуть пацієнтів на дистанційній реабілітації.', 'Physical therapy clinics, hospitals and digital health services that run remote rehabilitation for patients.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
