-- Exer Health — Здоров'я та краса › Реабілітація та фізіотерапія
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'exer.ai' OR LOWER(`name`) = LOWER('Exer Health'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Exer Health', NULL, 'https://www.exer.ai', NULL, NULL, 'Клінічний AI для оцінки рухів: застосунок Exer Health стежить за технікою домашніх вправ через камеру, а Exer Scan вимірює рухливість суглобів на прийомі.', 'Clinical AI for movement assessment: the Exer Health app watches home-exercise form through the camera, and Exer Scan measures joint mobility at the clinic.', 'Exer AI розробляє програмне забезпечення для оцінки та супроводу пацієнтів із проблемами опорно-рухового апарату на основі комп''ютерного зору. Exer Health — застосунок для пацієнта: під час домашніх вправ він через камеру телефона чи планшета перевіряє техніку, дає підказки в реальному часі та фіксує, чи дотримується людина програми. Exer Scan використовують у клініці для об''єктивного вимірювання рухливості, окремі модулі охоплюють кисть і зап''ясток (Exer Hands) та аналіз ходи (Exer Gait, бета). Ні датчиків, ні носимих пристроїв не потрібно. Програмне забезпечення має статус медичного виробу класу II FDA та інтегрується з електронними медкартами. Напрями — ортопедія, неврологія, профілактика падінь у літніх людей, фізіотерапія. Продукт продається клінікам і страховим планам; ціни не опубліковано.', 'Exer AI builds computer-vision software to assess and support patients with musculoskeletal problems. Exer Health is the patient app: during home exercise it uses the phone or tablet camera to check form, gives real-time cues and records whether the person sticks to the programme. Exer Scan is used in the clinic for objective mobility measurement, and separate modules cover the hand and wrist (Exer Hands) and gait analysis (Exer Gait, beta). No sensors or wearables are needed. The software is an FDA Class II medical device and integrates with electronic health records. Use cases include orthopaedics, neurology, fall prevention in older adults and physical therapy. It is sold to clinics and health plans; pricing is not published.', 'Перевірка техніки домашніх вправ через камеру
Об''єктивне вимірювання рухливості в клініці (Exer Scan)
Модулі для кисті й зап''ястка та аналізу ходи
Медичний виріб класу II FDA, інтеграція з медкартами', 'Home-exercise form checks through the camera
Objective mobility measurement in the clinic (Exer Scan)
Modules for hand and wrist and gait analysis
FDA Class II medical device, EHR integration', 'Ортопедичні й фізіотерапевтичні клініки та їхні пацієнти, які виконують призначені вправи вдома.', 'Orthopaedic and physical therapy clinics and their patients who do prescribed exercises at home.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
