SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'flok.health' OR LOWER(`name`) = LOWER('Flok Health'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Flok Health', NULL, 'https://www.flok.health', NULL, NULL, 'AI-клініка фізіотерапії у застосунку: консультації 24/7 без черг, персональна програма вправ при болю в спині, коліні чи артрозі, з підтримкою живих фізіотерапевтів.', 'An AI physiotherapy clinic in an app: 24/7 appointments with no waiting lists and a personal exercise plan for back pain, knee pain or osteoarthritis, backed by human physiotherapists.', 'Flok Health позиціонує себе як перша у світі AI-клініка фізіотерапії. У застосунку пацієнт у будь-який час проходить консультацію з AI-фізіотерапевтом: той розпитує про симптоми, оцінює стан і складає програму вправ, а далі коригує її за результатами. Напрями — біль у спині та коліні, остеоартроз та інші проблеми опорно-рухового апарату. За потреби підключаються живі фізіотерапевти. У Великій Британії Flok має сертифікацію медичного виробу класу IIa та реєстрацію CQC як постачальник AI-допомоги, співпрацює з трастами NHS. Доступ надається через організації-партнери, які надсилають пацієнтам посилання; ціни не опубліковано.', 'Flok Health presents itself as the world''s first AI physiotherapy clinic. In the app a patient can see an AI physiotherapist at any time: it asks about symptoms, assesses the condition and builds an exercise programme, then adjusts it based on results. Areas covered include back and knee pain, osteoarthritis and other musculoskeletal problems. Human physiotherapists step in when needed. In the UK Flok holds Class IIa medical device certification and CQC registration as an AI care provider, and works with NHS trusts. Access is provided through partner organisations that send patients a link; pricing is not published.', 'Консультації з AI-фізіотерапевтом 24/7 без черг
Персональна програма вправ із коригуванням за результатами
Підтримка живих фізіотерапевтів
Медичний виріб класу IIa, реєстрація CQC (Велика Британія)', '24/7 AI physiotherapist appointments with no waiting lists
Personal exercise plan adjusted to your results
Support from human physiotherapists
Class IIa medical device, CQC-registered (UK)', 'Пацієнти з болем у спині, коліні чи остеоартрозом, які отримують доступ через NHS або іншу організацію-партнера.', 'Patients with back pain, knee pain or osteoarthritis who get access through the NHS or another partner organisation.', 'mobile', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
