-- Aescape — Здоров'я та краса › Масаж і відновлення
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'aescape.com' OR LOWER(`name`) = LOWER('Aescape'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Aescape', NULL, 'https://www.aescape.com', NULL, NULL, 'Роботизований масаж з AI: система сканує тіло, будує його карту й виконує масаж двома роботизованими руками; тиск, музику й екран можна змінювати під час сесії.', 'AI robotic massage: the system scans your body, builds a body map and massages you with two robotic arms; pressure, music and visuals can be changed during the session.', 'Aescape — роботизований масаж на основі AI. На початку сесії система сканує тіло й будує його 3D-карту, щоб точно націлювати рухи двох роботизованих рук. Масаж виконується в одязі, без олії та підготовки. Під час сесії можна в реальному часі змінювати тиск, звук і зображення на екрані, а наступні сесії враховують попередні. Тривалість — 15, 30, 45 або 60 хвилин. Установки Aescape працюють у понад 140 партнерських локаціях у США — фітнес-клубах і спа; записатися можна через застосунок за містом, поштовим індексом чи назвою партнера. Пакети сесій: Reset — 3 сесії по 30 хв за $147, Recovery — 6 сесій по 45 хв за $414, Ritual — 12 сесій по 15 хв за $348 (на сайті часто діють знижки). Не замінює медичний масаж при травмі.', 'Aescape is AI-powered robotic massage. At the start of a session the system scans your body and builds a 3D body map so its two robotic arms can target movements precisely. The massage is done fully clothed, with no oil or preparation. During the session you can change pressure, audio and on-screen visuals in real time, and later sessions build on earlier ones. Sessions last 15, 30, 45 or 60 minutes. Aescape units operate at more than 140 partner locations in the US — gyms and spas — and you book through the app by city, ZIP code or partner name. Session packs: Reset — 3 × 30 min for $147, Recovery — 6 × 45 min for $414, Ritual — 12 × 15 min for $348 (the site often runs discounts). It does not replace medical massage after an injury.', '3D-сканування тіла й масаж двома роботизованими руками
Зміна тиску, звуку й зображення під час сесії
Сесії 15–60 хв, у одязі, без олії
Понад 140 локацій у США, запис через застосунок', '3D body scan and massage with two robotic arms
Adjust pressure, audio and visuals during the session
15–60 min sessions, fully clothed, no oil
140+ US locations, booking through the app', 'Відвідувачі фітнес-клубів і спа в США, які хочуть регулярний масаж для відновлення без запису до масажиста.', 'Gym and spa visitors in the US who want regular recovery massage without booking a therapist.', 'mobile', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
