-- Therabot — Здоров'я та краса › Масаж і відновлення
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'therabot.com' OR LOWER(`name`) = LOWER('Therabot'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Therabot', NULL, 'https://therabot.com', NULL, NULL, 'Роботизований масажер для ніг, що сам рухається вздовж ноги, з AI-терапевтом у застосунку: описуєте голосом чи текстом, що болить, і він складає програму масажу.', 'A robotic leg massager that moves along your leg by itself, with an AI therapist in the app: describe what hurts by voice or text and it builds a massage programme.', 'Therabot — носимий роботизований масажер для ніг. Пристрій надягають на ногу, і він сам рухається вздовж неї, масажуючи трьома роликами — це втричі більше покриття, ніж у масажного ролика. У застосунку працює AI-терапевт: досить написати чи сказати, наприклад, «глибше попрацюй з литкою, легше біля щиколотки», і він складе персональну програму, а під час сесії змінить інтенсивність за голосовою командою. Є чотири режими масажу та змінні ролики; тиск — до 18 фунтів у моделі Core і до 25 фунтів у Max, батарея — 1,5 та 3 години відповідно. Пристрій зараз на передзамовленні: ціна від $499 до $699 залежно від моделі, перші 1000 пристроїв почнуть відвантажувати 6 жовтня 2026 року. У застосунку є платна підписка Pro з фірмовими програмами.', 'Therabot is a wearable robotic leg massager. You put it on your leg and it moves along the limb by itself, massaging with three rollers — three times the coverage of a foam roller. The app includes an AI therapist: just type or say something like "deep work on my calf, easy on my ankle" and it builds a personal programme, then changes intensity mid-session on a voice command. There are four massage patterns and swappable rollers; pressure goes up to 18 lb on the Core model and 25 lb on the Max, with 1.5 and 3 hours of battery respectively. The device is on pre-order: $499 to $699 depending on the model, and the first 1,000 units begin shipping on 6 October 2026. The app has a paid Pro subscription with signature programmes.', 'Автоматичний масаж ніг трьома роликами
AI-терапевт складає програму за текстовим чи голосовим описом
Зміна інтенсивності голосом під час сесії
Чотири режими масажу та змінні ролики', 'Automatic leg massage with three rollers
AI therapist builds a programme from a text or voice description
Voice control of intensity during the session
Four massage patterns and swappable rollers', 'Спортсмени й активні люди, які хочуть відновлювати м''язи ніг удома без масажиста чи ручного масажного ролика.', 'Athletes and active people who want to recover leg muscles at home without a therapist or a manual foam roller.', 'mobile', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
