INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', 'Therabot is a wearable robotic leg massager. You put it on your leg and it moves along the limb by itself, massaging with three rollers — three times the coverage of a foam roller. The app includes an AI therapist: just type or say something like "deep work on my calf, easy on my ankle" and it builds a personal programme, then changes intensity mid-session on a voice command. There are four massage patterns and swappable rollers; pressure goes up to 18 lb on the Core model and 25 lb on the Max, with 1.5 and 3 hours of battery respectively. The device is on pre-order: $499 to $699 depending on the model, and the first 1,000 units begin shipping on 6 October 2026. The app has a paid Pro subscription with signature programmes.', 'manual' FROM DUAL WHERE @new = 1;
