-- Therabody — Здоров'я та краса › Масаж і відновлення
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'therabody.com' OR LOWER(`name`) = LOWER('Therabody'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Therabody', NULL, 'https://www.therabody.com', NULL, NULL, 'Застосунок до масажних пістолетів Theragun з безкоштовним AI-тренером Coach: складає персональний план відновлення за вашими цілями та даними з Garmin, Apple Health чи Strava.', 'The companion app for Theragun massage guns with the free AI Coach: it builds a personal recovery plan from your goals and data from Garmin, Apple Health or Strava.', 'Therabody — виробник масажних пістолетів Theragun та інших пристроїв для відновлення. У безкоштовному застосунку Therabody працює Coach — AI-функція, яка складає персональний план відновлення на основі ваших цілей, болючих зон, щоденної активності та наукових даних. Coach підключається до Garmin, Apple Health, Strava і Google Health Connect, протягом дня коригує план під фактичні навантаження та надсилає рекомендації. Застосунок пропонує готові програми від спортивних фахівців і фіксує сесії — тип терапії, тривалість, швидкість; окремі моделі (PRO Plus, Prime Plus, Sense, Mini 3-го покоління) записують сесії офлайн і синхронізують їх пізніше. Застосунок і Coach безкоштовні для iOS та Android, але для масажу потрібен власний пристрій Theragun, який купується окремо.', 'Therabody makes Theragun massage guns and other recovery devices. The free Therabody app includes Coach, an AI feature that builds a personal recovery plan from your goals, sore areas, daily activity and the latest research. Coach connects to Garmin, Apple Health, Strava and Google Health Connect, adjusts the plan through the day to your actual training load and sends recommendations. The app offers routines designed by sports scientists and logs sessions — therapy type, length and speed; some models (PRO Plus, Prime Plus, Sense, Mini 3rd Gen) record sessions offline and sync them later. The app and Coach are free on iOS and Android, but massage requires your own Theragun device, bought separately.', 'AI-тренер Coach з персональним планом відновлення
Синхронізація з Garmin, Apple Health, Strava, Google Health Connect
Готові програми від спортивних фахівців
Запис сесій масажу, зокрема офлайн на окремих моделях', 'AI Coach with a personal recovery plan
Sync with Garmin, Apple Health, Strava and Google Health Connect
Routines designed by sports scientists
Massage session logging, including offline on some models', 'Власники масажних пістолетів Theragun, спортсмени й люди, які регулярно тренуються та хочуть системно відновлюватися.', 'Theragun owners, athletes and people who train regularly and want a structured recovery routine.', 'mobile', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
SET @pid = (SELECT `id` FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'therabody.com' OR LOWER(`name`) = LOWER('Therabody')) ORDER BY `id` LIMIT 1);
INSERT IGNORE INTO `product_categories` (`product_id`, `category_id`) SELECT @pid, c.`id` FROM `categories` c WHERE @pid IS NOT NULL AND c.`slug` = 'health-beauty' LIMIT 1;
INSERT IGNORE INTO `product_subcategories` (`product_id`, `subcategory_id`) SELECT @pid, s.`id` FROM `subcategories` s JOIN `categories` c ON c.`id` = s.`category_id` WHERE @pid IS NOT NULL AND c.`slug` = 'health-beauty' AND s.`slug` = 'massage-recovery' LIMIT 1;
INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'short_description', 'en', 'The companion app for Theragun massage guns with the free AI Coach: it builds a personal recovery plan from your goals and data from Garmin, Apple Health or Strava.', 'manual' FROM DUAL WHERE @new = 1;
INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', 'Therabody makes Theragun massage guns and other recovery devices. The free Therabody app includes Coach, an AI feature that builds a personal recovery plan from your goals, sore areas, daily activity and the latest research. Coach connects to Garmin, Apple Health, Strava and Google Health Connect, adjusts the plan through the day to your actual training load and sends recommendations. The app offers routines designed by sports scientists and logs sessions — therapy type, length and speed; some models (PRO Plus, Prime Plus, Sense, Mini 3rd Gen) record sessions offline and sync them later. The app and Coach are free on iOS and Android, but massage requires your own Theragun device, bought separately.', 'manual' FROM DUAL WHERE @new = 1;
INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'main_features', 'en', 'AI Coach with a personal recovery plan
Sync with Garmin, Apple Health, Strava and Google Health Connect
Routines designed by sports scientists
Massage session logging, including offline on some models', 'manual' FROM DUAL WHERE @new = 1;
INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'target_audience', 'en', 'Theragun owners, athletes and people who train regularly and want a structured recovery routine.', 'manual' FROM DUAL WHERE @new = 1;
INSERT INTO `pricing_plans` (`product_id`, `plan_name`, `plan_name_en`, `price`, `period`, `description`, `description_en`) SELECT @pid, 'Безкоштовно', 'Free', 0.00, 'free', 'Застосунок і AI-тренер Coach безкоштовні; пристрій Theragun купується окремо', 'The app and AI Coach are free; a Theragun device is bought separately' FROM DUAL WHERE @new = 1;
SET @plan = IF(@new = 1, (SELECT `id` FROM `pricing_plans` WHERE `product_id` = @pid AND `plan_name` = 'Безкоштовно' ORDER BY `id` DESC LIMIT 1), NULL);
INSERT IGNORE INTO `pricing_plan_translations` (`plan_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @plan, 'plan_name', 'en', 'Free', 'manual' FROM DUAL WHERE @plan IS NOT NULL;
INSERT IGNORE INTO `pricing_plan_translations` (`plan_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @plan, 'description', 'en', 'The app and AI Coach are free; a Theragun device is bought separately', 'manual' FROM DUAL WHERE @plan IS NOT NULL;
